"use client";

import { useState, useTransition } from "react";
import { BookOpen, FileText, Globe2, Plus, Save, Trash2 } from "lucide-react";
import { AtualizarMemoriaAlphaSeo } from "@/actions/AlphaSeoProjectMemory";
import { SeoCard } from "../shared/PageHeader";

interface Section { key: string; title: string | null; content: string }
interface Competitor { domain: string; name: string | null; notes: string | null }
interface KeyPage { url: string; role: string; topic: string | null; notes: string | null }
interface Research { id: string; summary: string; entryDate: string | Date }

export function MemoryWorkspace({ projectId, sections: initialSections, competitors: initialCompetitors, keyPages: initialPages, researchLog: initialResearch }: { projectId: string; sections: Section[]; competitors: Competitor[]; keyPages: KeyPage[]; researchLog: Research[] }) {
  const [sections, setSections] = useState(initialSections);
  const [competitors, setCompetitors] = useState(initialCompetitors);
  const [pages, setPages] = useState(initialPages);
  const [research, setResearch] = useState(initialResearch);
  const [message, setMessage] = useState("");
  const [pending, start] = useTransition();
  function update(payload: Record<string, unknown>, success: () => void) { start(async () => { const result = await AtualizarMemoriaAlphaSeo({ projectId, updates: [payload] }); if (!result.success) return setMessage(result.error); success(); setMessage("Memória do projeto atualizada."); }); }
  function addCompetitor(data: FormData) { const domain = String(data.get("domain") ?? ""); const name = String(data.get("name") ?? "") || null; const notes = String(data.get("notes") ?? "") || null; update({ kind: "upsertCompetitor", domain, name, notes }, () => setCompetitors((rows) => [...rows.filter((row) => row.domain !== domain), { domain, name, notes }])); }
  function addPage(data: FormData) { const url = String(data.get("url") ?? ""); const role = String(data.get("role") ?? "OTHER"); const topic = String(data.get("topic") ?? "") || null; update({ kind: "upsertKeyPage", url, role, topic, notes: null }, () => setPages((rows) => [...rows.filter((row) => row.url !== url), { url, role, topic, notes: null }])); }
  function addResearch(data: FormData) { const summary = String(data.get("summary") ?? ""); update({ kind: "appendResearch", summary }, () => setResearch((rows) => [{ id: crypto.randomUUID(), summary, entryDate: new Date().toISOString() }, ...rows])); }
  return <div className="space-y-4">
    {sections.map((section, index) => <SeoCard key={section.key} className="p-5"><input aria-label="Título da seção" value={section.title ?? section.key} onChange={(event) => setSections((rows) => rows.map((row, rowIndex) => rowIndex === index ? { ...row, title: event.target.value } : row))} className="w-full bg-transparent text-base font-bold text-white outline-none"/><textarea aria-label={`Conteúdo de ${section.title ?? section.key}`} value={section.content} onChange={(event) => setSections((rows) => rows.map((row, rowIndex) => rowIndex === index ? { ...row, content: event.target.value } : row))} rows={5} className="mt-3 w-full rounded-xl border border-white/10 bg-slate-950/70 p-3 text-sm leading-6 text-slate-300 outline-none"/><button type="button" disabled={pending || !section.content.trim()} onClick={() => update({ kind: "upsertSection", key: section.key, title: section.title, content: section.content }, () => undefined)} className="mt-3 inline-flex min-h-11 items-center gap-2 rounded-xl border border-white/10 px-3 text-xs font-bold"><Save size={14}/>Salvar seção</button></SeoCard>)}
    <div className="grid gap-4 xl:grid-cols-2"><CollectionCard icon={Globe2} title="Concorrentes"><form action={addCompetitor} className="grid gap-2"><input name="domain" required placeholder="concorrente.com" className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-sm"/><input name="name" placeholder="Nome opcional" className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-sm"/><textarea name="notes" placeholder="Por que acompanha este concorrente?" className="rounded-xl border border-white/10 bg-slate-950 p-3 text-sm"/><AddButton pending={pending}/></form><Rows>{competitors.map((row) => <MemoryRow key={row.domain} title={row.name || row.domain} detail={row.notes || row.domain} onDelete={() => update({kind:"deleteCompetitor",domain:row.domain},()=>setCompetitors((rows)=>rows.filter((item)=>item.domain!==row.domain)))}/>)}</Rows></CollectionCard>
    <CollectionCard icon={FileText} title="Páginas-chave"><form action={addPage} className="grid gap-2"><input name="url" type="url" required placeholder="https://site.com/pagina" className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-sm"/><div className="grid grid-cols-2 gap-2"><select name="role" className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-sm"><option value="MONEY">Money</option><option value="HUB">Hub</option><option value="SPOKE">Spoke</option><option value="OTHER">Outra</option></select><input name="topic" placeholder="Tópico" className="min-h-11 rounded-xl border border-white/10 bg-slate-950 px-3 text-sm"/></div><AddButton pending={pending}/></form><Rows>{pages.map((row) => <MemoryRow key={row.url} title={`${row.role} · ${row.topic || "Sem tópico"}`} detail={row.url} onDelete={() => update({kind:"deleteKeyPage",url:row.url},()=>setPages((rows)=>rows.filter((item)=>item.url!==row.url)))}/>)}</Rows></CollectionCard></div>
    <CollectionCard icon={BookOpen} title="Research log"><form action={addResearch} className="flex flex-col gap-2 sm:flex-row"><textarea name="summary" required placeholder="Resumo da pesquisa paga e conclusões reutilizáveis" className="min-h-20 flex-1 rounded-xl border border-white/10 bg-slate-950 p-3 text-sm"/><AddButton pending={pending}/></form><Rows>{research.map((row) => <MemoryRow key={row.id} title={new Date(row.entryDate).toLocaleDateString("pt-BR")} detail={row.summary}/>)}</Rows></CollectionCard>
    {message && <p role="status" className="text-sm text-slate-400">{message}</p>}
  </div>;
}

function CollectionCard({ icon: Icon, title, children }: { icon: typeof Globe2; title: string; children: React.ReactNode }) { return <SeoCard className="p-5"><h2 className="flex items-center gap-2 font-bold text-white"><Icon size={16} className="text-[rgb(var(--seo-accent))]"/>{title}</h2><div className="mt-4 space-y-4">{children}</div></SeoCard>; }
function AddButton({ pending }: { pending: boolean }) { return <button disabled={pending} className="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl bg-[rgb(var(--seo-accent))] px-4 text-xs font-black text-slate-950"><Plus size={13}/>Adicionar</button>; }
function Rows({ children }: { children: React.ReactNode }) { return <div className="divide-y divide-white/[.05] border-t border-white/5">{children}</div>; }
function MemoryRow({ title, detail, onDelete }: { title: string; detail: string; onDelete?: () => void }) { return <div className="flex items-start justify-between gap-3 py-3"><div className="min-w-0"><p className="text-xs font-bold text-white">{title}</p><p className="mt-1 break-all text-xs leading-5 text-slate-500">{detail}</p></div>{onDelete && <button type="button" onClick={onDelete} className="grid size-11 shrink-0 place-items-center rounded-xl text-rose-300" aria-label={`Excluir ${title}`}><Trash2 size={14}/></button>}</div>; }
